SELECT  FROM TB_HR_CAND c 

  AND c.job_cd=#{filter.jobCode}
  AND c.grade_cd=#{filter.gradeCode}
  AND c.emp_type_cd=#{filter.employeeTypeCode}
  AND c.cntc_stat_cd=#{filter.contactStatusCode}
  AND c.input_psbl_dt <= #{availableThrough}

ORDER BY CASE WHEN c.cntc_stat_cd IN ('HOLD','CTRT') THEN 1 ELSE 0 END,
  c.input_psbl_dt,c.cand_id

mapper.insert:
INSERT INTO TB_HR_CAND_CNTC(cand_id,cntc_sn,cntc_stat_cd,cntc_memo,cntc_dt,reg_user_id,reg_dttm)
SELECT #{candidateId},COALESCE(MAX(h.cntc_sn),0)+1,#{status},#{memo},#{today},#{actor},clock_timestamp()
FROM TB_HR_CAND_CNTC h WHERE h.cand_id=#{candidateId}
